def topological_sort(nodes, edges):
    def _push(heap, item):
        heap.append(item)
        i = len(heap) - 1
        while i > 0:
            parent = (i - 1) // 2
            if heap[parent] <= heap[i]:
                break
            heap[parent], heap[i] = heap[i], heap[parent]
            i = parent

    def _pop(heap):
        last = heap.pop()
        if not heap:
            return last
        smallest = heap[0]
        heap[0] = last
        i = 0
        n = len(heap)
        while True:
            left = 2 * i + 1
            right = 2 * i + 2
            smallest_idx = i
            if left < n and heap[left] < heap[smallest_idx]:
                smallest_idx = left
            if right < n and heap[right] < heap[smallest_idx]:
                smallest_idx = right
            if smallest_idx == i:
                break
            heap[i], heap[smallest_idx] = heap[smallest_idx], heap[i]
            i = smallest_idx
        return smallest

    node_set = set(nodes)
    adjacency = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}
    seen_edges = set()

    for edge in edges:
        source, destination = edge
        if source not in node_set or destination not in node_set:
            raise ValueError("Edge endpoint not present in nodes: {}".format(edge))
        if (source, destination) in seen_edges:
            continue
        seen_edges.add((source, destination))
        adjacency[source].append(destination)
        in_degree[destination] += 1

    heap = []
    for node in nodes:
        if in_degree[node] == 0:
            _push(heap, node)

    result = []
